import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int na = nextInt(), nb = nextInt(), q = nextInt();
        long[] a = new long[na], b = new long[nb];
        for (int i = 0; i < na; i++) a[i] = nextLong();
        for (int i = 0; i < nb; i++) b[i] = nextLong();
        // frequency of every current value in b
        HashMap<Long, Integer> counts = new HashMap<>(4 * (nb + q) + 4);
        for (long x : b) counts.merge(x, 1, Integer::sum);
        StringBuilder sb = new StringBuilder();
        while (q-- > 0) {
            if (nextInt() == 0) {
                int i = nextInt();
                long x = nextLong();
                counts.merge(b[i], -1, Integer::sum);
                b[i] += x;
                counts.merge(b[i], 1, Integer::sum);
            } else {
                long target = nextLong(), total = 0;
                for (long v : a) {
                    Integer c = counts.get(target - v);
                    if (c != null) total += c;
                }
                sb.append(total).append('\n');
            }
        }
        if (sb.length() == 0) sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	na, nb, q := readInt(), readInt(), readInt()
	a := make([]int, na)
	b := make([]int, nb)
	for i := range a {
		a[i] = readInt()
	}
	for i := range b {
		b[i] = readInt()
	}
	// frequency of every current value in b
	counts := make(map[int]int, nb)
	for _, x := range b {
		counts[x]++
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	wrote := false
	for ; q > 0; q-- {
		if readInt() == 0 {
			i, x := readInt(), readInt()
			counts[b[i]]--
			b[i] += x
			counts[b[i]]++
		} else {
			target, total := readInt(), 0
			for _, v := range a {
				total += counts[target-v]
			}
			w.WriteString(strconv.Itoa(total))
			w.WriteByte('\n')
			wrote = true
		}
	}
	if !wrote {
		w.WriteByte('\n')
	}
}
